transformResponse(originalResponses) {
    return originalResponses.map((originalResponse, index) => {
        const { signerFields, contractNumber, expiresInDays, variableValues } = originalResponse;

        const signers = [];
        const signerKeys = Object.keys(signerFields).filter(key =>
            key.match(/Firmante\d+_Nombre/)
