                documento: signerFields[`Firmante${signerIndex}_Documento`] || "",
                signer_order: parseInt(signerIndex),
            };

            signers.push(signer);
        });

        if (signers.length === 0 && this.modelItem.default_signers) {
            this.modelItem.default_signers.forEach((defaultSigner, idx) => {
                signers.push({
                    nombres: defaultSigner.firstname || "",
                    apellidos: defaultSigner.lastname || "",
                    correo: defaultSigner.email || "",
