                    documento: defaultSigner.id_number || "",
                    signer_order: idx + 1,
                });
            });
        }

        const signerOrder2 =
            signers.find((s) => s.signer_order === 2) ||
            signers.find((s) => s.signer_order === 1) ||
            signers[0] || {};

        return {
            contract_number: contractNumber,
            expires_in_days: expiresInDays,
            signers: signers,
            signerOrder2: signerOrder2,
            variableValues: variableValues || {},
            selectable: true,
            uid: `${contractNumber}-${index}`,
        };
    });
},

