                });
                if (response && response.status && response.data) {
                    this.savedMappingConfig = response.data;
                } else {
                    this.savedMappingConfig = null;
                }
            } catch (error) {
                console.error('Error cargando config de mapeo:', error);
                this.savedMappingConfig = null;
            }
        },

        onMappingConfirmed({ mappings }) {
            this.mappingDialogVisible = false;

            this.importResponseData.forEach(record => {
                const newVariableValues = {};
                mappings.forEach(mapping => {
                    if (mapping.pdfVariable) {
                        const pdfVarName = mapping.pdfVariable.replace(/\[\$|\]/g, '');
                        const excelVarName = mapping.excelHeader.replace('VAR_', '');
                        newVariableValues[pdfVarName] = record.variableValues[excelVarName] || '';
                    }
                });
                record.variableValues = newVariableValues;
            });

            this.fillTable(this.importResponseData, this.importDocumentHeaderId);
        },

        async onSaveMappingConfig(config) {
            try {
                await this.$axios({
                    buildURL: {
                        key: 'admin.signatureRequest.saveMappingConfig',
                    },
                    data: {
                        documentPackageHeaderId: this.document.id,
                        mappingConfig: config,
                        detailFields: this.allPdfFields,
                    },
                    alert: true,
                });
                this.savedMappingConfig = config;
            } catch (error) {
                console.error('Error guardando config de mapeo:', error);
            }
        }
    },
};
